import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../../../providers/global/wallets_provider.dart';
import '../../../../wallets/wallet/wallet_mixin_interfaces/view_only_option_interface.dart';
import '../../../../widgets/custom_tab_view.dart';
import '../../../../widgets/rounded_white_container.dart';
import 'desktop_receive.dart';
import 'desktop_send.dart';

class MyWallet extends ConsumerStatefulWidget {
  const MyWallet({super.key, required this.walletId});

  final String walletId;

  @override
  ConsumerState<MyWallet> createState() => _MyWalletState();
}

class _MyWalletState extends ConsumerState<MyWallet> {
  final titles = ["Send", "Receive"];

  late final bool isViewOnly;

  @override
  void initState() {
    final wallet = ref.read(pWallets).getWallet(widget.walletId);

    isViewOnly = wallet is ViewOnlyOptionInterface && wallet.isViewOnly;
    if (isViewOnly) {
      titles.remove("Receive");
    }

    super.initState();
  }

  @override
  Widget build(BuildContext context) {
    if (isViewOnly) {
      return ListView(
        primary: false,
        children: [
          RoundedWhiteContainer(
            padding: EdgeInsets.zero,
            child: Padding(
              padding: const EdgeInsets.all(20),
              child: DesktopReceive(walletId: widget.walletId),
            ),
          ),
        ],
      );
    }

    return ListView(
      primary: false,
      children: [
        RoundedWhiteContainer(
          padding: EdgeInsets.zero,
          child: CustomTabView(
            titles: titles,
            children: [
              Padding(
                padding: const EdgeInsets.all(20),
                child: DesktopSend(walletId: widget.walletId),
              ),
              Padding(
                padding: const EdgeInsets.all(20),
                child: DesktopReceive(walletId: widget.walletId),
              ),
            ],
          ),
        ),
      ],
    );
  }
}
